theorem isTwistedEquivariant_comp {F F' : O ⥤ O} {θ θ' : MulAut G}
    (h : IsTwistedEquivariant d θ F) (h' : IsTwistedEquivariant d θ' F') :
    IsTwistedEquivariant d (θ' * θ) (F ⋙ F')

theorem isTwistedEquivariant_inv {F Finv : O ⥤ O} {θ : MulAut G}
    (hi : F ⋙ Finv = 𝟭 O) (ih : Finv ⋙ F = 𝟭 O) (h : IsTwistedEquivariant d θ F) :
    IsTwistedEquivariant d θ⁻¹ Finv

theorem stateStabilizer_le {C : Type*} [Category C] (L : S ⥤ C) {X : Type*}
    [MulAction (strictLawStabilizer L) X] (σ : X) :
    stateStabilizer L σ ≤ strictLawStabilizer L

theorem existsUnique_ΛHomθOver_mul_of_ΦθOver_eq (d : OEData G p) (H : Subgroup (StrictAut S))
    (θ : H →* MulAut G) [IsConnected S] {e₁ e₂ : AutBoxGθOver d H θ}
    (h : ΦθOver d H θ e₁ = ΦθOver d H θ e₂) : ∃! g : G, e₂ = ΛHomθOver d H θ g * e₁

theorem PreservesCleavage.map_chi (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) {s t : S} (u : s ⟶ t) (y : O) (hy : p.obj y = t)
    {hy' : p.obj (F.obj y) = A.obj t}
    (hsrc : F.obj (d.reind u y hy) = d.reind (A.map u) (F.obj y) hy') :
    F.map (d.chi u y hy) = eqToHom hsrc ≫ d.chi (A.map u) (F.obj y) hy'

theorem eq_liftOver {s t : S} {u : s ⟶ t} {x y : O} {hx : p.obj x = s} {hy : p.obj y = t}
    (f : x ⟶ y) (hf : p.map f = eqToHom hx ≫ u ≫ eqToHom hy.symm) :
    f = m.liftOver u hx hy

@[simp] theorem componentMultiplier_mk (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) (s : S) :
    componentMultiplier d pc (compMk s) = liftMultiplier d F s

theorem liftMultiplier_factors_through_components (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) :
    ∃! κ : CategoryTheory.ConnectedComponents S → G, ∀ s, liftMultiplier d F s = κ (compMk s)

theorem natTrans_descent_of_eq (σ : StrictSection p) {F F' : O ⥤ C} {E E' : S ⥤ C}
    (hE : p ⋙ E = F) (hE' : p ⋙ E' = F') (α : F ⟶ F') :
    ∃! β : E ⟶ E', Functor.whiskerLeft p β = eqToHom hE ≫ α ≫ eqToHom hE'.symm

theorem natTrans_descent_of_eq (m : MinSpec G p) {F F' : O ⥤ C} {E E' : S ⥤ C}
    (hE : p ⋙ E = F) (hE' : p ⋙ E' = F') (α : F ⟶ F') :
    ∃! β : E ⟶ E', Functor.whiskerLeft p β = eqToHom hE ≫ α ≫ eqToHom hE'.symm

theorem natTrans_descent_of_eq (d : OEData G p) {F F' : O ⥤ C} {E E' : S ⥤ C}
    (hE : p ⋙ E = F) (hE' : p ⋙ E' = F') (α : F ⟶ F') :
    ∃! β : E ⟶ E', Functor.whiskerLeft p β = eqToHom hE ≫ α ≫ eqToHom hE'.symm

theorem residualAction_trivial_of_factors (d : OEData G p) {F : O ⥤ C}
    (hF : OEData.IsInvariant d F) (hE : ∃ E : S ⥤ C, p ⋙ E = F) (s : S) :
    residualAction d F hF s = 1

theorem verticallyTrivial_of_residualAction_trivial (d : OEData G p) {F : O ⥤ C}
    (hF : OEData.IsInvariant d F) (h1 : ∀ s, residualAction d F hF s = 1) :
    VerticallyTrivial p F

theorem factors_of_residualAction_trivial (d : OEData G p) {F : O ⥤ C}
    (hF : OEData.IsInvariant d F) (h1 : ∀ s, residualAction d F hF s = 1) :
    ∃ E : S ⥤ C, p ⋙ E = F

theorem no_invariant_calibration_of_residualAction_ne_one (d : OEData G p) {F : O ⥤ C}
    (hF : OEData.IsInvariant d F) {s : S} (hs : residualAction d F hF s ≠ 1) :
    ¬ ∃ (L : S ⥤ C) (α : F ≅ p ⋙ L), IsInvariantNatTrans d hF (isInvariant_comp_p d L) α.hom

theorem parallel_basepoints_const_unique [Nonempty S] (d d' : OEData G p) {c c' : G}
    (hc : ∀ s, d'.base s = d.act (d.base s) c) (hc' : ∀ s, d'.base s = d.act (d.base s) c') :
    c = c'

theorem multiplier_unique (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S} {k : S → G}
    (hk : ∀ x, F.obj x = d.act (d.base (A.obj (p.obj x))) (k (p.obj x) * d.coord x)) :
    k = liftMultiplier d F

theorem liftMultiplier_eq_of_hom (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) {s t : S} (u : s ⟶ t) :
    liftMultiplier d F s = liftMultiplier d F t

theorem liftMultiplier_const (d : OEData G p) [IsConnected S] {F : O ⥤ O} {A : S ⥤ S}
    (pc : PreservesCleavage d F A) (s t : S) :
    liftMultiplier d F s = liftMultiplier d F t

theorem exists_unique_eq_liftFunctor_comp_Λ (d : OEData G p) [IsConnected S] {F : O ⥤ O}
    {A : S ⥤ S} (hF : IsGEquivariant d F) (pc : PreservesCleavage d F A) :
    ∃! a : G, F = liftFunctor d A ⋙ Λ d a

theorem sectionFunctor_comp_eq_of_obj (d : OEData G p) {F : O ⥤ O} {A : S ⥤ S}
    (hc : F ⋙ p = p ⋙ A) (c : G) (h : ∀ s, F.obj (d.base s) = d.act (d.base (A.obj s)) c) :
    d.sectionFunctor ⋙ F = A ⋙ d.sectionFunctor ⋙ d.actFunctor c

theorem preservesCleavage_iff_exists_base_obj (d : OEData G p) [IsConnected S] {F : O ⥤ O}
    {A : S ⥤ S} (hF : IsGEquivariant d F) (hc : F ⋙ p = p ⋙ A) :
    PreservesCleavage d F A ↔ ∃ c : G, ∀ s, F.obj (d.base s) = d.act (d.base (A.obj s)) c

theorem lift_obj_act_base_twisted (d : OEData G p) {θ : MulAut G} {F : O ⥤ O} {A : S ⥤ S}
    (hF : IsTwistedEquivariant d θ F) (hc : F ⋙ p = p ⋙ A) (s : S) (g : G) :
    F.obj (d.act (d.base s) g) = d.act (d.base (A.obj s)) (liftMultiplier d F s * θ g)

theorem multiplier_unique_twisted (d : OEData G p) {θ : MulAut G} {F : O ⥤ O} {A : S ⥤ S}
    {k : S → G}
    (hk : ∀ x, F.obj x = d.act (d.base (A.obj (p.obj x))) (k (p.obj x) * θ (d.coord x))) :
    k = liftMultiplier d F

theorem eq_liftByMultiplierθ (d : OEData G p) {θ : MulAut G} {F : O ⥤ O} {A : S ⥤ S}
    (hF : IsTwistedEquivariant d θ F) (hc : F ⋙ p = p ⋙ A) :
    F = liftByMultiplierθ d A θ (liftMultiplier d F)

theorem exists_unique_eq_liftFunctorθ_comp_Λ (d : OEData G p) [IsConnected S] {θ : MulAut G}
    {F : O ⥤ O} {A : S ⥤ S} (hF : IsTwistedEquivariant d θ F) (pc : PreservesCleavage d F A) :
    ∃! a : G, F = liftFunctorθ d A θ ⋙ Λ d a

theorem isInvariantNatTrans_comp (d : OEData G p) {F F' F'' : O ⥤ C} {hF : OEData.IsInvariant d F}
    {hF' : OEData.IsInvariant d F'} {hF'' : OEData.IsInvariant d F''} {α : F ⟶ F'} {β : F' ⟶ F''}
    (hα : IsInvariantNatTrans d hF hF' α) (hβ : IsInvariantNatTrans d hF' hF'' β) :
    IsInvariantNatTrans d hF hF'' (α ≫ β)

theorem OEData.IsInvariant.verticallyTrivial_iff_residualAction_trivial {d : OEData G p}
    {F : O ⥤ C} (hF : d.IsInvariant F) :
    VerticallyTrivial p F ↔ ∀ s, residualAction d F hF s = 1

theorem OEData.IsInvariant.normalFormQ_comp_residualData {d : OEData G p} {F : O ⥤ C}
    (hF : d.IsInvariant F) :
    (normalFormTo d ⋙ residualQ S G) ⋙ hF.residualData.toFunctor = F

theorem OEData.IsInvariant.residualData_unique {d : OEData G p} {F : O ⥤ C}
    (hF : d.IsInvariant F) {D : ResidualData S C G}
    (hD : (normalFormTo d ⋙ residualQ S G) ⋙ D.toFunctor = F) : D = hF.residualData

theorem natTrans_app_cast {D : Type*} [Category D] {F F' : D ⥤ C} (α : F ⟶ F') {X Y : D}
    (e : X = Y) (h₁ : F.obj X = F.obj Y) (h₂ : F'.obj Y = F'.obj X) :
    α.app X = eqToHom h₁ ≫ α.app Y ≫ eqToHom h₂

@[simp] theorem comparison_restrictComparison {D D' : ResidualData S C G}
    (α : D.presentationFunctor ⟶ D'.presentationFunctor) :
    comparison (restrictComparison α) = α

theorem holFunctor_ext {C : Type*} [Category C] {F F' : C ⥤ HolTotal Γ G}
    (hobj : ∀ x, F.obj x = F'.obj x)
    (hmap : ∀ {x y : C} (f : x ⟶ y), ((F.map f).1 : Γ) = (F'.map f).1) : F = F'

theorem IsHolLift.obj_pt {ρ : Γ →* G} {F : HolTotal Γ G ⥤ HolTotal Γ G}
    {A : SingleObj Γ ⥤ SingleObj Γ} (hF : IsHolLift ρ F A) (x : HolTotal Γ G) :
    (F.obj x).2.pt = (F.obj (holBase (SingleObj.star Γ))).2.pt * x.2.pt

theorem IsHolLift.map_fst {ρ : Γ →* G} {F : HolTotal Γ G ⥤ HolTotal Γ G}
    {A : SingleObj Γ ⥤ SingleObj Γ} (hF : IsHolLift ρ F A) {x y : HolTotal Γ G} (f : x ⟶ y) :
    ((F.map f).1 : Γ) = A.map f.1

theorem IsHolLift.mem_Eρ {ρ : Γ →* G} {F : HolTotal Γ G ⥤ HolTotal Γ G}
    {A : StrictAut (SingleObj Γ)} (hF : IsHolLift ρ F A.hom) :
    ((F.obj (holBase (SingleObj.star Γ))).2.pt, θSingleObjEquiv Γ A) ∈ Eρ ρ

theorem recordSpace_val_congr {τ : ℝ} {I : RecDom} (x : recordSpace τ I) {j k : Fin 3}
    (hj : j ∈ I.dom) (hk : k ∈ I.dom) (h : j = k) :
    (x : ↥I.dom → ℝ) ⟨j, hj⟩ = (x : ↥I.dom → ℝ) ⟨k, hk⟩
